sp_widget.client_script:
api.controller = function($scope, $window, $location) {

  var c = this;

  // ── Stats counter ─────────────────────────────────────────────────────────
  c.countByBadge = function(badgeClass) {
    if (!c.data || !c.data.applications) return 0;
    return c.data.applications.filter(function(a) {
      return a.badge_class === badgeClass;
    }).length;
  };

  // ── View Modal ────────────────────────────────────────────────────────────
  c.modalOpen = false;
  c.selected  = {};
  c.activeTab = 'personal';

  c.openModal = function(app) {
    c.selected  = app;
    c.activeTab = 'personal';
    c.modalOpen = true;
    document.body.style.overflow = 'hidden';
  };

  c.closeModal = function() {
    c.modalOpen = false;
    c.selected  = {};
    document.body.style.overflow = '';
  };

  c.setTab = function(tab) { c.activeTab = tab; };

  // ── Utilities ─────────────────────────────────────────────────────────────
  c.formatBytes = function(bytes) {
    if (!bytes || bytes == 0) return '0 B';
    var b = parseInt(bytes);
    if (b < 1024)    return b + ' B';
    if (b < 1048576) return (b / 1024).toFixed(1) + ' KB';
    return (b / 1048576).toFixed(1) + ' MB';
  };

  c.getFileIcon = function(ct) {
    if (!ct) return 'fa-file-o';
    if (ct.indexOf('pdf')   > -1) return 'fa-file-pdf-o';
    if (ct.indexOf('image') > -1) return 'fa-file-image-o';
    if (ct.indexOf('word')  > -1) return 'fa-file-word-o';
    if (ct.indexOf('excel') > -1 || ct.indexOf('sheet') > -1) return 'fa-file-excel-o';
    return 'fa-file-o';
  };

  // ── Navigation ────────────────────────────────────────────────────────────
  c.goBack = function() {
    $location.url('/applicant?id=applicant_dashboard');
  };

  // ── Timeline Toggle ───────────────────────────────────────────────────────
  c.expandedApp = null;
  c.appTimeline = [];

  c.toggleTimeline = function(app) {
    if (c.expandedApp === app.sys_id) {
      c.expandedApp = null;
      c.appTimeline = [];
      return;
    }
    c.expandedApp = app.sys_id;
    c.appTimeline = (c.data.timelines && c.data.timelines[app.sys_id]) || [];
  };

  // ── Escape closes modal ───────────────────────────────────────────────────
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') {
      $scope.$apply(function() {
        if (c.modalOpen) c.closeModal();
      });
    }
  });

};

sp_widget.css:
/* ═══════════════════════════════════════
   LAYOUT — sidebar + main content
═══════════════════════════════════════ */
.gn-layout {
  margin-left: -15px;
  margin-right: -15px;
  margin-top: 35px;
  display: flex;
  align-items: stretch;
  min-height: 100vh;
  background: #f0f2f5;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  position: relative;
}
.gn-layout *,
.gn-layout *::before,
.gn-layout *::after {
  box-sizing: border-box;
}

/* ═══════════════════════════════════════
   SIDEBAR
═══════════════════════════════════════ */
.sidebar {
  width: 220px;
  flex-shrink: 0;
  background: #fff;
  border-right: 1px solid #e5e7eb;
  position: sticky;
  top: 0;
  height: 100vh;
  align-self: flex-start;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  z-index: 10;
  scrollbar-width: none;
}
.sidebar::-webkit-scrollbar { display: none; }

/* ═══════════════════════════════════════
   MAIN WRAP
═══════════════════════════════════════ */
.mya-wrap {
  flex: 1;
  min-width: 0;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  background: #f0f2f5;
  padding: 28px 32px 56px;
  box-sizing: border-box;
  min-height: 100vh;
}

/* ═══════════════════════════════════════
   PAGE HEADER
═══════════════════════════════════════ */
.mya-page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
  margin-bottom: 10px;
}
.mya-page-hd-left { display: flex; align-items: center; gap: 14px; }
.mya-page-hd-icon {
  width: 48px; height: 48px; border-radius: 14px; flex-shrink: 0;
  background: linear-gradient(135deg, #4f46e5, #7c3aed);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 20px;
  box-shadow: 0 4px 14px rgba(79,70,229,0.35);
}
.mya-page-title { font-size: 24px; font-weight: 900; color: #0f172a; margin: 0; line-height: 1.2; }
.mya-page-sub   { font-size: 13px; color: #64748b; margin: 4px 0 0; }

.mya-btn-back {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 9px 18px; border-radius: 10px;
  background: #fff; border: 1px solid #e2e8f0;
  font-size: 13px; font-weight: 700; color: #374151;
  cursor: pointer; transition: all .18s;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
}
.mya-btn-back:hover { background: #f8fafc; box-shadow: 0 3px 10px rgba(0,0,0,0.09); }

/* ═══════════════════════════════════════
   BREADCRUMB
═══════════════════════════════════════ */
.mya-breadcrumb {
  display: flex; align-items: center; gap: 6px;
  font-size: 12px; margin-bottom: 20px;
}
.mya-bc-link { color: #6366f1; font-weight: 600; text-decoration: none; }
.mya-bc-link:hover { text-decoration: underline; }
.mya-bc-sep  { color: #cbd5e1; font-size: 10px; }
.mya-bc-cur  { color: #64748b; font-weight: 600; }


/* ═══════════════════════════════════════
   TIMELINE PANEL
═══════════════════════════════════════ */
.mya-tl-panel {
  background: #fff;
  border: 1px solid #e8edf5;
  border-top: none;
  border-radius: 0 0 16px 16px;
  overflow: hidden;
  animation: myaSlideIn .22s ease-out;
  margin-bottom: 10px;
}
@keyframes myaSlideIn {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}
.mya-tl-inner { padding: 24px 28px 28px; }

.mya-tl-header {
  font-size: 11px; font-weight: 800; color: #475569;
  text-transform: uppercase; letter-spacing: .7px;
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 28px;
}
.mya-tl-appnum {
  font-size: 11px; font-weight: 700; color: #6366f1;
  background: #eef2ff; padding: 2px 8px; border-radius: 5px;
}

.mya-tl-empty {
  text-align: center; padding: 20px 0; color: #94a3b8; font-size: 13px;
}
.mya-tl-empty i { font-size: 24px; display: block; margin-bottom: 8px; }

/* ═══════════════════════════════════════
   HORIZONTAL STEPPER
═══════════════════════════════════════ */
.mya-stepper { width: 100%; overflow-x: auto; padding-bottom: 4px; }

.mya-stepper-track {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  min-width: 600px;
  position: relative;
}

/* Each step */
.mya-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  position: relative;
  text-align: center;
  min-width: 80px;
}

/* Connector line between steps */
.mya-step-conn {
  position: absolute;
  top: 18px;
  right: calc(50% + 20px);
  left: calc(-50% + 20px);
  height: 3px;
  background: #e2e8f0;
  z-index: 0;
}
.mya-step-conn-fill {
  height: 100%;
  width: 0%;
  background: #6366f1;
  transition: width .4s ease;
}
.mya-step-conn-fill--done { width: 100%; }

/* Circle */
.mya-step-circle {
  width: 38px; height: 38px;
  border-radius: 50%;
  border: 2.5px solid #e2e8f0;
  background: #f8fafc;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px;
  color: #fff;
  z-index: 1;
  position: relative;
  transition: all .25s;
  box-shadow: 0 2px 8px rgba(0,0,0,0.06);
}

.mya-step--pending .mya-step-circle {
  background: #f1f5f9;
  border-color: #e2e8f0;
  color: #cbd5e1;
  font-size: 12px;
}

.mya-step--done .mya-step-circle {
  color: #fff;
  box-shadow: 0 3px 10px rgba(0,0,0,0.12);
}

.mya-step--active .mya-step-circle {
  color: #fff;
  box-shadow: 0 0 0 5px rgba(99,102,241,0.15);
  animation: stepPulse 2s infinite;
}

.mya-step--decline .mya-step-circle {
  box-shadow: 0 0 0 5px rgba(239,68,68,0.15);
  animation: stepPulseRed 2s infinite;
}

@keyframes stepPulse {
  0%, 100% { box-shadow: 0 0 0 5px rgba(99,102,241,0.15); }
  50%       { box-shadow: 0 0 0 9px rgba(99,102,241,0.06); }
}
@keyframes stepPulseRed {
  0%, 100% { box-shadow: 0 0 0 5px rgba(239,68,68,0.15); }
  50%       { box-shadow: 0 0 0 9px rgba(239,68,68,0.06); }
}

/* Label */
.mya-step-label {
  font-size: 11px;
  font-weight: 700;
  color: #1e293b;
  margin-top: 10px;
  line-height: 1.3;
  max-width: 90px;
}
.mya-step--pending .mya-step-label { color: #94a3b8; font-weight: 600; }
.mya-step--decline .mya-step-label { color: #ef4444; }

/* Date */
.mya-step-date {
  font-size: 10px;
  color: #64748b;
  margin-top: 4px;
  line-height: 1.4;
}
.mya-step-date i { color: #94a3b8; }
.mya-step-date--pending {
  color: #cbd5e1;
  font-style: italic;
  font-size: 10px;
  margin-top: 4px;
}

/* Responsive: stack vertically on small screens */
@media (max-width: 640px) {
  .mya-stepper-track {
    flex-direction: column;
    align-items: flex-start;
    min-width: unset;
    gap: 0;
    padding-left: 18px;
  }
  .mya-step {
    flex-direction: row;
    align-items: flex-start;
    text-align: left;
    gap: 14px;
    padding-bottom: 24px;
    flex: unset;
    width: 100%;
  }
  .mya-step-conn {
    top: 38px;
    left: 17px;
    right: unset;
    width: 3px;
    height: 100%;
  }
  .mya-step-label { max-width: unset; margin-top: 6px; }
  .mya-step-date  { margin-top: 2px; }
  .mya-step-circle { flex-shrink: 0; }
}
/* ═══════════════════════════════════════
   STATS BAR
═══════════════════════════════════════ */
.mya-stats-bar {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 22px;
}
.mya-stat {
  display: flex; align-items: center; gap: 12px;
  padding: 14px 18px; border-radius: 14px;
  transition: transform .16s, box-shadow .16s;
}
.mya-stat:hover { transform: translateY(-2px); box-shadow: 0 6px 18px rgba(0,0,0,0.09); }
.mya-stat i       { font-size: 20px; opacity: .7; }
.mya-stat-val     { font-size: 22px; font-weight: 900; line-height: 1; }
.mya-stat-lbl     { font-size: 10px; font-weight: 600; color: #6b7280; margin-top: 2px; white-space: nowrap; }
.mya-stat--blue   { background: linear-gradient(135deg, #eff6ff, #dbeafe); border: 1px solid #bfdbfe; }
.mya-stat--blue i, .mya-stat--blue .mya-stat-val { color: #2563eb; }
.mya-stat--green  { background: linear-gradient(135deg, #f0fdf4, #dcfce7); border: 1px solid #86efac; }
.mya-stat--green i, .mya-stat--green .mya-stat-val { color: #16a34a; }
.mya-stat--amber  { background: linear-gradient(135deg, #fffbeb, #fef3c7); border: 1px solid #fde68a; }
.mya-stat--amber i, .mya-stat--amber .mya-stat-val { color: #d97706; }
.mya-stat--red    { background: linear-gradient(135deg, #fff5f5, #fee2e2); border: 1px solid #fecaca; }
.mya-stat--red i, .mya-stat--red .mya-stat-val { color: #dc2626; }
.mya-stat--purple { background: linear-gradient(135deg, #f5f3ff, #ede9fe); border: 1px solid #c4b5fd; }
.mya-stat--purple i,
.mya-stat--purple .mya-stat-val { color: #7c3aed; }

/* ═══════════════════════════════════════
   APPLICATION CARD LIST
═══════════════════════════════════════ */
.mya-list { display: flex; flex-direction: column; }

.mya-app-card {
  display: flex; align-items: stretch;
  background: #fff;
  border: 1px solid #e8edf5;
  overflow: hidden;
  transition: box-shadow .18s, transform .18s;
  cursor: pointer;
  border-radius: 0;
  margin-bottom: 0;
}
.mya-app-card:first-child  { border-radius: 16px 16px 0 0; }
.mya-app-card:last-of-type { border-radius: 0 0 16px 16px; }
.mya-app-card:only-child   { border-radius: 16px; }
.mya-app-card + .mya-app-card { border-top: none; }
.mya-app-card:hover {
  box-shadow: 0 4px 20px rgba(0,0,0,0.09);
  transform: translateY(-1px);
  z-index: 1; position: relative;
}
.mya-app-card--expanded {
  box-shadow: 0 0 0 2px #6366f1 inset;
  z-index: 2; position: relative;
}

/* Left accent bar */
.mya-card-accent                 { width: 5px; flex-shrink: 0; }
.mya-card-accent.badge-completed { background: linear-gradient(180deg, #16a34a, #4ade80); }
.mya-card-accent.badge-review    { background: linear-gradient(180deg, #0ea5e9, #38bdf8); }
.mya-card-accent.badge-new       { background: linear-gradient(180deg, #94a3b8, #cbd5e1); }
.mya-card-accent.badge-declined  { background: linear-gradient(180deg, #dc2626, #f87171); }
.mya-card-accent.badge-pending   { background: linear-gradient(180deg, #d97706, #fbbf24); }

/* Card body row */
.mya-card-body {
  flex: 1; display: flex; align-items: center;
  padding: 16px 20px; min-width: 0; gap: 0;
}

/* Columns */
.mya-col        { padding: 0 16px; }
.mya-col-app    { display: flex; align-items: center; gap: 12px; flex: 0 0 260px; min-width: 0; padding-left: 4px; }
.mya-col-prog   { flex: 0 0 180px; min-width: 0; }
.mya-col-status { flex: 0 0 170px; }
.mya-col-date   { flex: 1; min-width: 120px; }
.mya-col-actions { flex: 0 0 auto; padding-right: 4px; }

/* App avatar */
.mya-app-av {
  width: 40px; height: 40px; border-radius: 12px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 16px; color: #fff;
}
.mya-app-av.badge-completed { background: linear-gradient(135deg, #16a34a, #4ade80); }
.mya-app-av.badge-review    { background: linear-gradient(135deg, #0284c7, #38bdf8); }
.mya-app-av.badge-new       { background: linear-gradient(135deg, #64748b, #94a3b8); }
.mya-app-av.badge-declined  { background: linear-gradient(135deg, #dc2626, #f87171); }
.mya-app-av.badge-pending   { background: linear-gradient(135deg, #d97706, #fbbf24); }

.mya-app-num  { font-size: 14px; font-weight: 800; color: #1e293b; white-space: nowrap; }
.mya-app-date { font-size: 11px; color: #94a3b8; margin-top: 2px; white-space: nowrap; }

.mya-prog-label { font-size: 9px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: .5px; }
.mya-prog-name  { font-size: 12px; font-weight: 700; color: #1e293b; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mya-prog-none  { font-size: 11px; color: #cbd5e1; margin-top: 2px; }
.mya-prog-num   { font-size: 10px; color: #94a3b8; margin-top: 1px; }

/* ═══════════════════════════════════════
   BADGES
═══════════════════════════════════════ */
.mya-badge,
.ma-badge {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 11px; font-weight: 700; padding: 5px 12px;
  border-radius: 99px; white-space: nowrap;
}
.mya-badge i, .ma-badge i { font-size: 10px; }

.badge-completed   { background: #dcfce7; color: #15803d; border: 1px solid #86efac; }
.badge-review      { background: #e0f2fe; color: #0369a1; border: 1px solid #7dd3fc; }
.badge-new         { background: #f1f5f9; color: #475569; border: 1px solid #cbd5e1; }
.badge-declined    { background: #fee2e2; color: #b91c1c; border: 1px solid #fca5a5; }
.badge-pending     { background: #fef3c7; color: #b45309; border: 1px solid #fde68a; }
.badge-submitted   { background: #eff6ff; color: #3b82f6; border: 1px solid #bfdbfe; }
.badge-approved    { background: #f0fdf4; color: #16a34a; border: 1px solid #bbf7d0; }
.badge-closed      { background: #f8fafc; color: #64748b; border: 1px solid #e2e8f0; }
.badge-in-progress { background: #f0f9ff; color: #0369a1; border: 1px solid #7dd3fc; }

/* Date col */
.mya-date-label { font-size: 9px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: .5px; }
.mya-date-val   { font-size: 12px; font-weight: 600; color: #475569; margin-top: 2px; white-space: nowrap; }
.mya-date-val i { font-size: 10px; color: #94a3b8; }

/* Action buttons */
.mya-col-actions { display: flex; align-items: center; gap: 6px; }
.mya-act-btn {
  width: 34px; height: 34px; border-radius: 9px; border: none;
  display: flex; align-items: center; justify-content: center;
  font-size: 13px; cursor: pointer; transition: all .16s;
}
.mya-act-btn--tl       { background: #f1f5f9; color: #64748b; }
.mya-act-btn--tl:hover { background: #e0e7ff; color: #4f46e5; }
.mya-act-btn--view       { background: #f0fdf4; color: #16a34a; }
.mya-act-btn--view:hover { background: #dcfce7; }

/* ═══════════════════════════════════════
   TIMELINE PANEL
═══════════════════════════════════════ */
.mya-tl-panel {
  background: #fafbff;
  border: 1px solid #e8edf5;
  border-top: none;
  border-radius: 0 0 16px 16px;
  overflow: hidden;
  animation: myaSlideIn .22s ease-out;
  margin-bottom: 10px;
}
@keyframes myaSlideIn {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}
.mya-tl-inner  { padding: 20px 28px 24px; }
.mya-tl-header {
  font-size: 12px; font-weight: 800; color: #475569;
  text-transform: uppercase; letter-spacing: .7px;
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 18px;
}
.mya-tl-appnum {
  font-size: 11px; font-weight: 700; color: #6366f1;
  background: #eef2ff; padding: 2px 8px; border-radius: 5px;
}
.mya-tl-items { display: flex; flex-direction: column; gap: 0; }
.mya-tl-item  { display: flex; gap: 14px; }
.mya-tl-item-left {
  display: flex; flex-direction: column;
  align-items: center; flex-shrink: 0; width: 14px;
}
.mya-tl-dot {
  width: 14px; height: 14px; border-radius: 50%; flex-shrink: 0;
  border: 2px solid #fff; margin-top: 2px;
}
.mya-tl-connector {
  flex: 1; width: 2px; background: #e2e8f0;
  margin: 4px 0; min-height: 20px;
}
.mya-tl-item-body  { padding-bottom: 18px; }
.mya-tl-item-label { font-size: 13px; font-weight: 700; color: #1e293b; }
.mya-tl-item-date  { font-size: 11px; color: #94a3b8; margin-top: 3px; }
.mya-tl-empty {
  text-align: center; padding: 20px 0; color: #94a3b8; font-size: 13px;
}
.mya-tl-empty i { font-size: 24px; display: block; margin-bottom: 8px; }

/* ═══════════════════════════════════════
   EMPTY STATE
═══════════════════════════════════════ */
.mya-empty-state { text-align: center; padding: 64px 20px; }
.mya-empty-ico {
  width: 64px; height: 64px; border-radius: 18px;
  background: #f1f5f9; display: flex; align-items: center;
  justify-content: center; font-size: 26px;
  color: #94a3b8; margin: 0 auto 16px;
}
.mya-empty-state h3 { font-size: 16px; font-weight: 800; color: #1e293b; margin: 0 0 6px; }
.mya-empty-state p  { font-size: 13px; color: #64748b; margin: 0; }

/* ═══════════════════════════════════════
   MODAL OVERLAY & CONTAINER
═══════════════════════════════════════ */
.mya-overlay {
  position: fixed; inset: 0; z-index: 9000;
  background: rgba(15,23,42,0.55);
  backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center;
  padding: 20px;
  animation: myaFadeIn .18s ease;
}
@keyframes myaFadeIn { from { opacity: 0; } to { opacity: 1; } }
.mya-modal {
  background: #fff; border-radius: 20px;
  width: 100%; max-width: 720px;
  max-height: 90vh; overflow: hidden;
  display: flex; flex-direction: column;
  box-shadow: 0 24px 64px rgba(0,0,0,0.22);
  animation: myaModalIn .22s cubic-bezier(.34,1.56,.64,1);
}
@keyframes myaModalIn {
  from { opacity: 0; transform: scale(.95) translateY(16px); }
  to   { opacity: 1; transform: scale(1) translateY(0); }
}

/* Modal header */
.mya-mhdr {
  display: flex; align-items: center; justify-content: space-between;
  padding: 18px 22px 16px; border-bottom: 1px solid #f1f5f9;
  background: linear-gradient(135deg, #f8faff, #fff);
  flex-shrink: 0;
}
.mya-mhdr-left { display: flex; align-items: center; gap: 12px; }
.mya-mhdr-av {
  width: 42px; height: 42px; border-radius: 12px; flex-shrink: 0;
  background: linear-gradient(135deg, #6366f1, #8b5cf6);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 18px;
  box-shadow: 0 3px 10px rgba(99,102,241,0.3);
}
.mya-mhdr-title { font-size: 16px; font-weight: 800; color: #1e293b; }
.mya-mhdr-sub   { font-size: 11px; color: #94a3b8; margin-top: 2px; }
.mya-mhdr-close {
  width: 32px; height: 32px; border-radius: 8px;
  border: none; background: #f1f5f9; color: #64748b;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer; font-size: 13px; transition: background .15s;
}
.mya-mhdr-close:hover { background: #fee2e2; color: #dc2626; }

/* Modal banner */
.mya-mbanner {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 22px; background: #f8fafc;
  border-bottom: 1px solid #f1f5f9; flex-shrink: 0;
}
.mya-mbanner-date { font-size: 11px; color: #94a3b8; }

/* Modal tabs */
.mya-mtabs {
  display: flex; gap: 2px; padding: 0 22px;
  border-bottom: 1px solid #f1f5f9; background: #fff;
  overflow-x: auto; flex-shrink: 0;
}
.mya-mtab {
  padding: 12px 16px; border: none; background: transparent;
  font-size: 12px; font-weight: 700; color: #64748b;
  cursor: pointer; border-bottom: 2px solid transparent;
  margin-bottom: -1px; white-space: nowrap;
  transition: color .15s, border-color .15s;
  display: flex; align-items: center; gap: 5px;
}
.mya-mtab:hover  { color: #4f46e5; }
.mya-mtab.active { color: #5443AD; border-bottom-color: #5443AD; }
.mya-mtab-badge  {
  background: #5443AD; color: #fff;
  font-size: 9px; font-weight: 800;
  width: 16px; height: 16px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
}

/* Modal body */
.mya-mbody { flex: 1; overflow-y: auto; padding: 20px 22px; }

/* Section title */
.mya-sec-title {
  font-size: 11px; font-weight: 800; color: #94a3b8;
  text-transform: uppercase; letter-spacing: .8px;
  margin-bottom: 14px;
}
.mya-divider { height: 1px; background: #f1f5f9; margin: 20px 0; }

/* View grid */
.mya-view-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; margin-bottom: 4px; }
.mya-vfield    { background: #f8fafc; border: 1px solid #f1f5f9; border-radius: 10px; padding: 10px 14px; }
.mya-vflabel   { font-size: 10px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: .5px; }
.mya-vfvalue   { font-size: 13px; font-weight: 600; color: #1e293b; margin-top: 3px; }

/* Prose */
.mya-prose-field { margin-bottom: 14px; }
.mya-prose-val   {
  font-size: 13px; color: #374151; line-height: 1.6;
  background: #f8fafc; border: 1px solid #f1f5f9;
  border-radius: 10px; padding: 12px 14px; margin-top: 4px;
  white-space: pre-wrap;
}

/* Attachments */
.mya-no-attach { text-align: center; padding: 24px; color: #94a3b8; }
.mya-no-attach i { font-size: 24px; display: block; margin-bottom: 8px; }
.mya-no-attach p { font-size: 13px; font-weight: 600; margin: 0; }
.mya-attach-list { display: flex; flex-direction: column; gap: 8px; }
.mya-attach-item {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 14px; background: #f8fafc;
  border: 1px solid #f1f5f9; border-radius: 10px;
  transition: background .1s;
}
.mya-attach-item:hover { background: #f1f5f9; }
.mya-attach-ico  {
  width: 36px; height: 36px; border-radius: 9px;
  background: #eff6ff; border: 1px solid #e2e8f0;
  display: flex; align-items: center; justify-content: center;
  font-size: 15px; color: #5443AD; flex-shrink: 0;
}
.mya-attach-info { flex: 1; min-width: 0; }
.mya-attach-name { font-size: 12px; font-weight: 700; color: #1e293b; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mya-attach-size { font-size: 10px; color: #94a3b8; margin-top: 2px; }
.mya-attach-dl {
  width: 30px; height: 30px; border-radius: 7px;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; cursor: pointer; transition: all .15s; border: none;
  background: #EEEDFB; color: #5443AD; text-decoration: none;
}
.mya-attach-dl:hover { background: #ddd9f7; }

/* Modal footer */
.mya-mfooter {
  display: flex; align-items: center; justify-content: flex-end; gap: 10px;
  padding: 14px 22px; border-top: 1px solid #f1f5f9;
  background: #f8fafc; flex-shrink: 0;
}
.mya-mfoot-close {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 9px 18px; border-radius: 9px;
  background: #fff; border: 1.5px solid #e2e8f0;
  font-size: 13px; font-weight: 700; color: #374151;
  cursor: pointer; transition: all .15s;
}
.mya-mfoot-close:hover { background: #f1f5f9; }

/* ═══════════════════════════════════════
   RESPONSIVE
═══════════════════════════════════════ */
@media (max-width: 860px) {
  .mya-stats-bar { grid-template-columns: repeat(3, 1fr); }
  .mya-col-prog  { display: none; }
  .mya-col-app   { flex: 1; }
  .mya-view-grid { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .sidebar   { display: none; }
  .mya-wrap  { padding: 16px; }
}
@media (max-width: 580px) {
  .mya-stats-bar  { grid-template-columns: repeat(2, 1fr); }
  .mya-col-date   { display: none; }
  .mya-page-title { font-size: 18px; }
}

sp_widget.script:
(function () {

  data.sideBar      = $sp.getWidget('sidebar_dashboard');
  data.applications = [];
  data.timelines    = {};

  var applicantTable = 'x_enno_gatenow_service_applicants';
  var currentUser    = gs.getUserName();
  if (!currentUser) return;

  var formatDate = function (d) {
    if (!d || d === '' || d === 'null') return '';
    return String(d).split(' ')[0] || '';
  };

  function buildAppObject(applicantRec) {
    return {
      sys_id:                 applicantRec.getUniqueValue(),
      number:                 applicantRec.getValue('number')                         || '',
      first_name:             applicantRec.getValue('first_name')                     || '',
      middle_name:            applicantRec.getValue('middle_name')                    || '',
      last_name:              applicantRec.getValue('last_name')                      || '',
      birthdate:              formatDate(applicantRec.getValue('birthdate')),
      phone:                  applicantRec.getValue('phone_number')                   || '',
      email:                  applicantRec.getValue('email')                          || '',
      gender_display:         applicantRec.getDisplayValue('gender')                  || '',
      marital_display:        applicantRec.getDisplayValue('marital_status')          || '',
      race_display:           applicantRec.getDisplayValue('race')                    || '',
      ethnicity_display:      applicantRec.getDisplayValue('ethnicity')               || '',
      education_display:      applicantRec.getDisplayValue('education_level')         || '',
      military_display:       applicantRec.getDisplayValue('military_status')         || '',
      street:                 applicantRec.getValue('street')                         || '',
      city:                   applicantRec.getValue('city')                           || '',
      country:                applicantRec.getValue('country')                        || '',
      zip:                    applicantRec.getValue('zip_postal_code')                || '',
      applicant_type_display: applicantRec.getDisplayValue('applicant_type')          || '',
      citizenship_display:    applicantRec.getDisplayValue('citizenship_status')      || '',
      identity_display:       applicantRec.getDisplayValue('identity_type')           || '',
      tribal_display:         applicantRec.getDisplayValue('tribal_affiliation')      || '',
      disability_display:     applicantRec.getDisplayValue('disability_status')       || '',
      ssn:                    applicantRec.getValue('ssn')                            || '',
      tin_ein:                applicantRec.getValue('tin_ein')                        || '',
      uei:                    applicantRec.getValue('uei')                            || '',
      organization:           applicantRec.getValue('organization')                   || '',
      start_date:             formatDate(applicantRec.getValue('project_start_date')),
      end_date:               formatDate(applicantRec.getValue('project_end_date')),
      submission_date:        formatDate(applicantRec.getValue('submission_date')),
      requested_budget:       applicantRec.getValue('requested_budget')               || '',
      short_description:      applicantRec.getValue('short_description')              || '',
      proposal_description:   applicantRec.getValue('proposal_description')           || '',
      project_goals:          applicantRec.getValue('project_goals_and_objectives')   || '',
      project_activities:     applicantRec.getValue('project_activities_methodology') || '',
      state_display:          applicantRec.getDisplayValue('state')                   || 'New',
      updated_on:             applicantRec.getDisplayValue('sys_updated_on')          || ''
    };
  }

  // ── Maps ──────────────────────────────────────────────────────────────────
  var labelMap = {
    'new':                   'Application Created',
    'ready_for_review':      'Ready for Review',
    'review_in_progress':    'Review in Progress',
    'review_completed':      'Review Completed',
    'award_pending':         'Award Pending',
    'award_acknowledged':    'Award Acknowledged',
    'project_in_progress':   'Project in Progress',
    'project_completed':     'Project Completed',
    'closed':                'Closed',
    'declined_by_agency':    'Declined by Agency',
    'declined_by_applicant': 'Declined by Applicant'
  };

  var colorMap = {
    'new':                   '#9ca3af',
    'ready_for_review':      '#3b82f6',
    'review_in_progress':    '#f59e0b',
    'review_completed':      '#8b5cf6',
    'award_pending':         '#f97316',
    'award_acknowledged':    '#22c55e',
    'project_in_progress':   '#6366f1',
    'project_completed':     '#0ea5e9',
    'closed':                '#64748b',
    'declined_by_agency':    '#ef4444',
    'declined_by_applicant': '#ef4444'
  };

  var badgeMap = {
    'new':                   'badge-new',
    'ready_for_review':      'badge-review',
    'review_in_progress':    'badge-in-progress',
    'review_completed':      'badge-completed',
    'award_pending':         'badge-pending',
    'award_acknowledged':    'badge-completed',
    'project_in_progress':   'badge-in-progress',
    'project_completed':     'badge-completed',
    'closed':                'badge-closed',
    'declined_by_agency':    'badge-declined',
    'declined_by_applicant': 'badge-declined'
  };

  var normalStates = [
    'new',
    'ready_for_review',
    'review_in_progress',
    'review_completed',
    'award_pending',
    'award_acknowledged',
    'project_in_progress',
    'project_completed',
    'closed'
  ];

  // ── Query applications ────────────────────────────────────────────────────
  var applicantQuery = new GlideRecordSecure(applicantTable);
  applicantQuery.addQuery('sys_created_by', currentUser);
  applicantQuery.orderByDesc('sys_updated_on');
  applicantQuery.query();

  while (applicantQuery.next()) {
    var sysId     = applicantQuery.getUniqueValue();
    var stateVal  = applicantQuery.getValue('state') || 'new';
    var createdOn = applicantQuery.getDisplayValue('sys_created_on') || '';

    // ── Attachments ──────────────────────────────────────────────────────────
    var attachments     = [];
    var attachmentQuery = new GlideRecordSecure('sys_attachment');
    attachmentQuery.addQuery('table_name',   applicantTable);
    attachmentQuery.addQuery('table_sys_id', sysId);
    attachmentQuery.query();

    while (attachmentQuery.next()) {
      attachments.push({
        sys_id:       attachmentQuery.getUniqueValue(),
        name:         attachmentQuery.getValue('file_name')    || '',
        size:         attachmentQuery.getValue('size_bytes')   || '0',
        content_type: attachmentQuery.getValue('content_type') || ''
      });
    }

    var appObj              = buildAppObject(applicantQuery);
    appObj.program_name     = applicantQuery.getDisplayValue('program')          || 'N/A';
    appObj.program_num      = applicantQuery.getDisplayValue('program.number')   || '';
    appObj.program_category = applicantQuery.getDisplayValue('program_category') || '';
    appObj.badge_class      = badgeMap[stateVal]                                 || 'badge-new';
    appObj.created_on       = createdOn;
    appObj.attachments      = attachments;
    appObj.state_value      = stateVal;

    data.applications.push(appObj);

    // ── Build stepper steps (NO sys_audit — only current state value) ────────
    var isDeclined    = (stateVal === 'declined_by_agency' || stateVal === 'declined_by_applicant');
    var currentIdx    = normalStates.indexOf(stateVal);
    var timelineSteps = [];

    if (isDeclined) {

      // For declined: show all normal steps as completed, then append decline as current
      normalStates.forEach(function (s) {
        timelineSteps.push({
          state:  s,
          label:  labelMap[s],
          color:  colorMap[s],
          status: 'completed'
        });
      });

      timelineSteps.push({
        state:  stateVal,
        label:  labelMap[stateVal] || stateVal,
        color:  colorMap[stateVal] || '#ef4444',
        status: 'current'
      });

    } else {

      // For normal flow: mark steps before current as completed,
      // current as current, rest as pending
      normalStates.forEach(function (s, idx) {
        timelineSteps.push({
          state:  s,
          label:  labelMap[s],
          color:  colorMap[s],
          status: idx < currentIdx   ? 'completed'
                : idx === currentIdx  ? 'current'
                :                      'pending'
        });
      });

    }

    data.timelines[sysId] = timelineSteps;
  }

})();
